"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1275-01-01:0":{"b": ["اسماعیلیوں نے الموت پر دوبارہ قبضے کی کوشش کی؛ منگولوں نے پسپا کر دیا", "8ffd690c"], "d": ["ہلاکو کے 1256 میں الموت ڈھا دینے کے بعد اسماعیلی قلعے پر دوبارہ قبضے کے لیے متحرک ہوئے مگر منگولوں نے انہیں پسپا کر دیا (1275)۔", "4bb7e566"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0819-06-28:0":{"b": ["خلیفہ مامون نے سامان خدات کے پوتوں کو ماوراء النہر میں گورنری دی؛ سامانی خاندان کی بنیاد پڑی", "3c2e71a4"], "d": ["رافع بن لیث کی بغاوت کو کچلنے میں خدمات کے صلے میں مامون نے اسد بن سامان خدات کے بیٹوں میں سے نوح کو سمرقند، احمد کو فرغانہ، یحییٰ کو شاش اور الیاس کو ہرات کا گورنر مقرر کیا؛ خاندان چار شاخوں میں بٹ گیا۔", "1fd94252"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0840-01-01:0":{"b": ["اویغور سلطنت کے قرغیزوں کے ہاتھوں خاتمے (840) کے بعد کاشغر–بلاساغون کے علاقے میں قراخانی خاندان ظاہر ہوا", "56b2495a"], "d": ["840 میں اوتوکن کی اویغور سلطنت کے خاتمے پر مغرب کی طرف ہجرت کرنے والے یغما (پریتساک کے مطابق خاندان کے بانی) کاشغر کے علاقے میں آئے اور کچھ مقامات قارلوقوں سے لے لیے، پھر چو اور ایلی کی وادیوں میں پھیل گئے؛ بلاساغون، کاشغر کے ساتھ ایک اہم مرکز بنا۔", "657e062d"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0861-03-17:0":{"b": ["یعقوب بن لیث الصفار سیستان کا حاکم بنا؛ صفاری خاندان قائم ہوا", "0ded2f05"], "d": ["یعقوب بن لیث نے 247 (861) میں سیستان کا حاکم بننے کے بعد مشرق کی طرف بڑھ کر غزنہ، گردیز اور کابل-بامیان کے علاقے تک اپنی حکمرانی کا دائرہ وسیع کیا۔", "396bc394"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0874-10-16:0":{"b": ["خلیفہ معتمد نے نصر بن احمد کو ماوراء النہر کا انتظام دیا؛ اس کا بھائی اسماعیل بخارا کا گورنر بنا", "352c1588"], "d": ["261 (874-75) میں ماوراء النہر کا انتظام فرمان کے ذریعے نصر بن احمد کو دیا گیا؛ نصر نے اسی سال بخارا کے لوگوں کی خواہش پر اپنے بھائی اسماعیل بن احمد کو بخارا کا گورنر مقرر کیا۔ بعض محققین اس تاریخ کو ریاست کا قیام شمار کرتے ہیں۔", "3e55ae41"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0876-04-01:0":{"b": ["یعقوب بن لیث کو بغداد کے قریب دیر العاقول میں پہلی بار عباسی افواج کے ہاتھوں شکست ہوئی", "07f28ece"], "d": ["رجب 262 (اپریل 876) میں یعقوب کو بغداد سے 50 میل کے فاصلے پر دیر العاقول میں عباسی افواج کے مقابل زندگی میں پہلی بار شکست ہوئی؛ بدلہ لینے کی تیاری کرتے ہوئے فوت ہو گیا۔", "53d4cae4"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0879-06-09:0":{"b": ["یعقوب بن لیث فوت ہوا؛ اس کا بھائی عمرو بن لیث صفاری امیر بنا", "abca3596"], "d": ["یعقوب بن لیث 14 شوال 265 (9 جون 879) کو فوت ہوا؛ اس کی وصیت پر اس کا بھائی عمرو خاندان کا سربراہ بنا۔", "82e0d5fd"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0888-05-16:0":{"b": ["اسماعیل بن احمد نے سمرقند کے قریب اپنے بڑے بھائی نصر کو شکست دے کر قید کر لیا، اسے اس کے منصب پر رہنے دیا", "c2354f71"], "d": ["275 (888) میں سمرقند کے قریب نصر کو شکست ہوئی اور وہ قید کر لیا گیا؛ اسماعیل نے اس سے اچھا سلوک کیا اور اسے سمرقند بھیج دیا۔ نصر کی وفات (279/892) کے ساتھ حکمرانی اسماعیل کو منتقل ہو گئی۔", "136b0681"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0888-06-21:0":{"b": ["موفق نے کرمان، فارس اور خراسان عمرو بن لیث کو اقطاع میں دے دیے", "cc33d033"], "d": ["7 صفر 275 (21 جون 888) کو خمارویہ کی بغاوت کے باعث عمرو سے صلح کرنے والے موفق نے کرمان، فارس اور خراسان 10 ملین درہم کے عوض عمرو کو اقطاع میں دے دیے۔", "5e2f441c"]},
