"OLAYLAR_ORTACAG_IRAN_TURAN:0898-02-19:0":{"b": ["خلیفہ معتضد نے ماوراء النہر کی گورنری اسماعیل بن احمد سے لے کر عمرو بن لیث کو دے دی", "34173888"], "d": ["عمرو بن لیث کی درخواست پر خلیفہ نے سامانی امیر اسماعیل بن احمد کو ماوراء النہر کی گورنری سے معزول کر کے اس کی جگہ عمرو کو مقرر کیا (23 محرم 285 / 19 فروری 898)؛ اس فیصلے سے صفاریوں اور سامانیوں کے درمیان جنگ چھڑ گئی۔", "e1ba9603"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0900-04-19:0":{"b": ["اسماعیل بن احمد نے بلخ کے قریب صفاری امیر عمرو بن لیث کو شکست دے کر قید کر لیا؛ خراسان سامانیوں کے پاس چلا گیا", "caf82be8"], "d": ["15 ربیع الآخر 287 (19 اپریل 900) کو بلخ کے قریب ہونے والی جنگ میں اسماعیل بن احمد نے عمرو بن لیث کو شکست دے کر قید کر لیا؛ عمرو بغداد بھیج دیا گیا۔ خلیفہ نے اسماعیل کو خراسان، طبرستان اور دیلم کے منشور دیے؛ خراسان پر سامانی حاکم ہو گئے۔", "10e1c26d"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0902-01-01:0":{"b": ["قیدی عمرو بن لیث بغداد میں قتل کیا گیا؛ فارس عمرو کے پوتے طاہر کو دے دیا گیا", "ad0fc037"], "d": ["سامانیوں کے مطلوبہ فدیہ ادا نہ کرنے والے پوتوں کے باعث بغداد بھیجا گیا عمرو بن لیث وہیں قتل کر دیا گیا (289/902)؛ اسی سال خلیفہ مکتفی نے فارس کا علاقہ طاہر بن محمد کو دے دیا۔", "42a2b845"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0923-04-21:0":{"b": ["زرنج کے عیاروں نے ابو جعفر احمد کو اقتدار میں پہنچایا؛ صفاریوں کی خلفی شاخ قائم ہوئی", "6934302a"], "d": ["سیستان میں سامانی حکمرانی کے دوران اٹھنے والی بغاوتوں کے بعد زرنج کے عیاروں نے 311 (923) میں ابو جعفر احمد بن محمد بن خلف کو اقتدار میں پہنچایا؛ اس نے اپنی حکمرانی کا دائرہ بست اور رخج تک بڑھا دیا۔", "828e328d"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0932-01-01:0":{"b": ["بویہی علی نے اصفہان پر قبضہ کر لیا؛ بویہی خاندان نے ایران کے مغرب میں حکمرانی قائم کرنا شروع کی", "2f945d58"], "d": ["دیلمی بویہ کے بیٹے علی نے زیاری مرداویج کے خلاف خلیفہ کی حمایت حاصل کرنے کے لیے جنوب کی طرف اتر کر اصفہان پر قبضہ کر لیا (932)؛ مرداویج کے حلیفوں سے سامنا ہونے پر شہر چھوڑ کر فارس کا رخ کیا۔", "a989c5f8"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0943-04-06:0":{"b": ["نصر بن احمد فوت ہوا؛ اس کا بیٹا نوح اول سامانی امیر بنا", "1d70ce88"], "d": ["نصر دوم 27 رجب 331 (6 اپریل 943) کو تپِ دق سے فوت ہوا؛ اس کی جگہ اس کا بیٹا نوح بیٹھا (TDV سامانی: وفات 331/943)۔", "3af02c79"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0949-01-01:0":{"b": ["عماد الدولہ علی نرینہ اولاد چھوڑے بغیر فوت ہوا؛ فارس عضد الدولہ کے پاس چلا گیا", "e1e844c4"], "d": ["خاندان کے سربراہ عماد الدولہ علی کے نرینہ اولاد چھوڑے بغیر فوت ہونے پر (949) فارس کے علاقے پر رکن الدولہ کا بیٹا عضد الدولہ حاکم ہو گیا۔", "dc1fa68e"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0963-01-01:0":{"b": ["الپتگین نے غزنہ لویکیوں سے لے کر غزنوی سلطنت کی بنیاد رکھی", "05bf004d"], "d": ["سامانی خراسان فوج کے سپہ سالار الپتگین نے 961 میں سامانی تخت پر اپنا امیدوار بٹھانے کی کوشش میں ناکام ہو کر اپنے ساتھ کی تھوڑی سی فوج کے ساتھ غزنہ کی طرف پسپائی اختیار کی اور مقامی لویک خاندان کو ہٹا کر شہر پر قبضہ کر لیا (ذوالحجہ 351 / جنوری 963)۔", "263f0b5b"]},
"OLAYLAR_ORTACAG_IRAN_TURAN:0963-04-01:0":{"b": ["ابو جعفر احمد قتل ہوا؛ اس کا بیٹا خلف الصفار سیستان کا امیر بنا", "01ed7a39"], "d": ["ابو جعفر ربیع الاول 352 (اپریل 963) میں ایک غلام کے ہاتھوں شراب کی محفل میں قتل ہوا؛ اس کی جگہ اس کا بیٹا ابو احمد خلف الصفار بیٹھا۔", "af0883d0"]},
