"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1066-09-25:0":{"b": ["ہرالد ہاردراڈے سٹیمفورڈ برج میں مارا گیا", "a9e2a898"], "d": ["ناروے کا بادشاہ ہرالد ہاردراڈے 25 ستمبر 1066 کو انگلستان میں سٹیمفورڈ برج (یارک شائر) میں مارا گیا؛ ہرالد نے 1043/44 میں کیف کے عظیم شہزادے یاروسلاو کی بیٹی الیزیو سے شادی کی تھی۔", "654f1496"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1068-01-01:0":{"b": ["جنگِ مسلمیری: نارمنوں نے پالرمو کا راستہ کاٹنے والی مسلم فوج کو شکست دی", "362ca837"], "d": ["1068 میں پالرمو کے قریب مسلمیری میں نارمنوں نے اہم فتح پائی اور پالرمو جانے والے راستوں کا کنٹرول سنبھال لیا۔", "555852a2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1068-01-01:1":{"b": ["زیری بیڑے کے ساتھ آنے والے ایوب کے آدمیوں نے جزیرے کے مسلمانوں کے ممتاز امیر ابن الحواس کو قتل کر دیا", "8367d1fb"], "d": ["زیری بیڑے کے ساتھ آنے والے ایوب کے آدمی جزیرے کے مسلمانوں کے ممتاز امیر ابن الحواس کو قتل کرتے ہیں (460)۔", "6c81c4c0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1072-01-01:0":{"b": ["پالرمو نے کاؤنٹ راجر اور رابرٹ گیسکار کے آگے ہتھیار ڈالے؛ اسلامی دارالحکومت نارمن ہو گیا", "f7be77c0"], "d": ["پانچ ماہ کے بری اور بحری محاصرے کے بعد پالرمو نے 1072 میں نرم شرائط پر ہتھیار ڈال دیے؛ راجر نے شہر اپنے بڑے بھائی رابرٹ گیسکار کے نام پر لیا۔ راجر نے اسی سال سے «کاؤنٹ آف سسلی» کا لقب استعمال کیا۔", "44fe7ca7"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1077-01-01:0":{"b": ["کانوسا کا سفر: ہائنرش چہارم نے پوپ گریگوری ہفتم کے سامنے ماتیلدا کے قلعے میں معافی مانگی", "c55345ff"], "d": ["پوپ گریگوری ہفتم اور شہنشاہ ہائنرش چہارم کے درمیان تقرری کے تنازع (Investitür Kavgası) کی انتہا 1077 میں ماتیلدا کے قلعۂ کانوسا میں ہوئی؛ شہنشاہ پوپ کے سامنے ذلیل ہوا۔", "0ceb34d7"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1082-01-01:0":{"b": ["بازنطینی شہنشاہ الیکسیوس کومنینوس نے وینس کو سنہری فرمان (کرائسوبول) کے ذریعے وسیع تجارتی مراعات دیں", "dbb20bd5"], "d": ["نارمنوں کے خلاف دی گئی بحری امداد کے بدلے مئی 1082 میں جاری ہونے والے کرائسوبول سے وینس والوں کو بازنطینی سلطنت میں ٹیکس سے مستثنیٰ تجارت کا حق ملا؛ Treccani کے مطابق یہ مراعات صلیبی جنگوں میں شرکت سے بڑھائی گئیں اور چوتھی صلیبی جنگ میں عروج کو پہنچیں۔", "0b3ae24d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1085-07-17:0":{"b": ["رابرٹ گیسکار کیفالونیا میں فوت ہوا؛ راجر بورسا آپولیا کا ڈیوک بنا", "e1dbeef9"], "d": ["رابرٹ گیسکار کیفالونیا میں فوت ہوتا ہے؛ اس کا مقرر کردہ وارث راجر بورسا آپولیا کا ڈیوک بنتا ہے۔ Treccani بھی وفات کی تاریخ کی تصدیق کرتا ہے: «quando la morte lo colpiva il 17 luglio 1085» (Enciclopedia Italiana «Roberto il Guiscardo»)۔", "ab676a5f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1086-07-10:0":{"b": ["Knud چہارم (مقدس Knud) اودنسے کے Sankt Albani کلیسا میں قتل کیا گیا", "6654e332"], "d": ["1080 سے ڈنمارک کا بادشاہ Knud چہارم انگلستان پر نئی مہم کی تیاری کر رہا تھا کہ 10 جولائی 1086 کو اودنسے کے Sankt Albani کلیسا میں قتل کر دیا گیا؛ 1100 میں اسے ولی قرار دیا گیا۔", "e1f2de9a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1096-01-01:0":{"b": ["آلتھنگ نے آئس لینڈ کا پہلا ٹیکس، یعنی کلیسائی عُشر، منظور کیا (1096-97)", "eb2602c1"], "d": ["بشپ Gissur Ísleifsson کی کوشش سے آلتھنگ نے آئس لینڈ کا پہلا حقیقی ٹیکس، یعنی کلیسائی عُشر، منظور کیا (1096-97 کے آلتھنگ؛ سال)۔ SNL «Islands historie»: «Under hans sønn Gissur ble tiende innført, og det ble også opprettet et bispesete på Hólar»۔", "dd8908e8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1097-01-01:0":{"b": ["میلان کمیونی قائم ہوئی (عمل کی تکمیل)", "b0acfa2b"], "d": ["گیارہویں صدی کے وسط کی پاتاریا تحریک اور کلیسائی اصلاحات کی کشمکش کے بعد میلان کمیونی کے ادارہ بننے کا عمل 1097 کے لگ بھگ مکمل ہوا مانا جاتا ہے۔", "53d0a31a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1097-01-01:1":{"b": ["لیوبیچ کانگریس: knez نے باپ سے ملی زمین اپنے پاس رکھنے کا اصول مان لیا", "5d95e535"], "d": ["Volodymyr Monomakh کی پہل پر منعقد لیوبیچ کانگریس (1097) نے جانشینی کے نظام (rota نظام) کو جڑ سے بدل دیا؛ ہر knez اپنے باپ کا موروثی علاقہ اپنے پاس رکھے گا۔", "7ec0e84a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1098-01-01:0":{"b": ["بوہیمند نے انطاکیہ کے محاصرے میں مدد کرنے والے جنیوا والوں کو وسیع تجارتی مراعات دیں", "3c6b06d3"], "d": ["پہلی صلیبی جنگ کے دوران انطاکیہ کے محاصرے میں مدد دینے والے جنیوا والوں کو ٹارانتو کے بوہیمند نے شہر میں وسیع تجارتی مراعات دیں؛ جنیوا کی مشرقی بحیرۂ روم میں نوآبادکاری یوں شروع ہوئی۔", "f1cccd5f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1100-08-01:0":{"b": ["جنیوا کمیونی کی پہلی سرکاری صلیبی مہم روانہ ہوئی", "4be1bc2c"], "d": ["نجی صلیبی کوششوں (1097؛ Guglielmo Embriaco کی 1098-99 کی مہم) کے بعد جنیوا کمیونی کا پہلا سرکاری صلیبی بیڑا 1 اگست 1100 کو روانہ ہوا؛ مشرق میں جنیوا کی نوآبادیاتی سرگرمی کا آغاز ہوا۔", "2ac9e677"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1102-01-01:0":{"b": ["Kálmán نے کروشیا (1097-1102) اور دالماتیا (1102-1105) فتح کیے", "312e9720"], "d": ["کروات بغاوت کو کچلنے والے Kálmán نے 1097-1102 کے درمیان کروشیا فتح کیا؛ 1102-1105 کے دوران دالماتیا کے شہروں کو بھی ہنگری کے اقتدار میں لے لیا (زادار میں ہنگری کے تسلط کا آغاز 1105 یا 1107)۔ دالماتیا کے شہروں نے اپنی بلدیاتی مراعات برقرار رکھیں۔", "faa4f775"]},
