"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:1":{"b": ["مینداوگاس نے عیسائیت قبول کر کے لتھوانیا کے بادشاہ کے طور پر تاج پہنا", "424666af"], "d": ["مینداوگاس نے 1253 میں کیتھولک ہو کر بادشاہ کے طور پر تاج پہنا اور لتھوانیا کو مملکت قرار دیا؛ اس کے پیروکار بت پرستی کی طرف لوٹ گئے۔", "fc42f619"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1255-01-01:0":{"b": ["بوہیمیا کے بادشاہ اوتوکار دوم کے لیے توتونی جماعت کا قلعہ قائم ہوا: کونیگسبرگ", "4b6bb21c"], "d": ["بادشاہ اوتوکار دوم کی پروشیا میں صلیبی مہم کے دوران توتونی جماعت کے لیے بنائے گئے قلعے (1255) کے گرد بڑھنے والے شہر کو اس کے اعزاز میں کونیگسبرگ کا نام دیا گیا۔ شہر 1263 میں پروشیائیوں کی بغاوت میں تباہ ہوا، 1286 میں دوبارہ بنایا گیا۔", "7bc46742"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1257-01-01:0":{"b": ["گولیلمو بوکانیگرا نے عوامی کپتانی قائم کی", "b7753984"], "d": ["فریڈرک دوم کی 1250 کی وفات کے بعد پرانے اور نئے امیر خاندانوں (فیسکی، گریمالدی، دوریا، اسپینولا) کے مقابل بورژوازی نے 1257 میں گولیلمو بوکانیگرا کی قیادت میں 'عوامی کپتان' (capitano del Popolo) کا منصب قائم کیا؛ بوکانیگرا کی آمریت کی کوشش 1262 میں دبا دی گئی۔", "2eae2a56"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1258-08-11:0":{"b": ["مانفریڈ کی پالرمو میں صقلیہ کے بادشاہ کے طور پر تاج پوشی ہوئی", "95db5116"], "d": ["بھتیجے کونرادین کے مرنے کی افواہ پھیلانے والے مانفریڈ نے لوچیرا کے مسلمانوں کی حمایت سے مملکت پاپائی سفیر سے واپس لی اور 1258 میں پالرمو میں بادشاہ کے طور پر تاج پہنا۔", "1047b259"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1259-01-01:0":{"b": ["ایپیروس کے امیر میخائل دوم نے کورفو مانفریڈ کے حوالے کر دیا", "19f2de3c"], "d": ["1259 میں ایپیروس کے امیر میخائل دوم انجلوس کومنینوس نے کورفو صقلیہ کے بادشاہ مانفریڈ کے حوالے کر دیا؛ جزیرہ 1267 میں مملکتِ صقلیہ کے ساتھ آنژو کے شارل کو منتقل ہو کر آنژو کے بلقان میں اثر و رسوخ کا بحری اڈہ بنا۔", "1fe50b1f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1260-01-01:0":{"b": ["جنگِ مونتاپرتی: مانفریڈ کے گیبیلین حلیفوں نے ٹسکنی کے گیلفوں کو شکست دی؛ فلورنس دوبارہ گیبیلین ہو گیا", "7ee3d67e"], "d": ["1260 کی مونتاپرتی کی فتح مانفریڈ کی قسمت کا عروج بنی؛ فلورنس دوبارہ گیبیلین حکمرانی میں چلا گیا۔ مانفریڈ کی بینیونتو میں شکست (1266) اور تاغلیاکوتسو (1268) نے گیلفوں کی واپسی کروائی۔", "a3001f03"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1261-01-01:0":{"b": ["معاہدۂ نیمفایوم: جنیوا نے بازنطین سے بحرِ اسود اور مشرقی بحرِ روم کی تجارتی مراعات لیں", "194b1f15"], "d": ["بازنطینی شہنشاہ میخائل ہشتم سے 1261 میں طے پانے والے معاہدۂ نیمفایوم سے جنیوا نے بحرِ اسود اور مشرقی بحرِ روم کی وسیع مراعات حاصل کیں؛ پیرا-غلطہ کالونی اور کریمیا (کافہ) کی نوآبادکاری کی بنیاد یہی معاہدہ ہے۔", "6deda3b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:0":{"b": ["بونیفاچو بے اولاد فوت ہوا؛ چچا پیتروی دوم ساوائے کا کاؤنٹ بنا", "38fe8bbd"], "d": ["امیدیو چہارم کا کم سن بیٹا بونیفاچو 1263 میں بے اولاد فوت ہوا تو باپ کی وصیت کے برخلاف تومازو دوم کے بیٹے تومازو سوم کی جگہ اس کا بھائی پیترو دوم ('چھوٹا شارلمین') کاؤنٹ بنا۔", "c18af671"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:1":{"b": ["ستیپوتزی میں جنیوا وینس سے ہار گیا؛ کریمونا کی جنگ بندی طے ہوئی", "060e901b"], "d": ["نیمفایوم کے بعد جاری رہنے والی جنیوا-وینس جنگ 1263 میں ستیپوتزی میں جنیوا کی شکست اور کریمونا کی جنگ بندی پر ختم ہوئی۔", "83eacbcb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:2":{"b": ["پروشیائیوں نے بغاوت کر کے کونیگسبرگ کا پہلا مرکز ڈھا دیا", "9b09b809"], "d": ["1263 میں عیسائی نوآبادکاروں کے خلاف اٹھنے والے پروشیائیوں نے کونیگسبرگ کا پہلا مرکز ڈھا دیا؛ شہر آج کی جگہ پر دوبارہ بسایا گیا (1286 میں شہر کا درجہ)۔", "63cc141a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-12-16:0":{"b": ["ہاکون چہارم جنگِ لارگز کے بعد اورکنی میں فوت ہوا", "7df398fd"], "d": ["اسکاٹ لینڈ میں ناروے کے دعووں کو مضبوط کرنے کے لیے 1263 میں ہیبرائیڈز کی مہم کرنے والا ہاکون چہارم جنگِ لارگز کے بعد اورکنی میں فوت ہوا؛ 1217 سے جاری حکمرانی ختم ہوئی۔ اس کے بیٹے میگنس لاگابوتے نے اسکاٹ لینڈ کے ساتھ جنگ ختم کی۔", "a7f678c4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1266-02-26:0":{"b": ["جنگِ بینیونتو: آنژو کے شارل نے مانفریڈ کو شکست دے کر قتل کیا؛ مملکت آنژو کو منتقل ہو گئی", "40101cec"], "d": ["26 فروری 1266 کو بینیونتو میں کاؤنٹ آف آنژو شارل نے مانفریڈ کی فوج کو تتر بتر کر دیا؛ مانفریڈ میدانِ جنگ میں مارا گیا۔ مملکتِ صقلیہ ہوہنشٹاؤفن سے آنژو خاندان کو منتقل ہو گئی۔", "35ac3334"]},
